result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-form/src/fix.js", "content": "/**
 * Transforms the inaccessible markup in fixtures/before.html into a
 * semantically correct, accessible form.
 */
export function fixForm(html) {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  const container = doc.querySelector('.form');

  // Real form element
  const form = doc.createElement('form');

  const makeField = (labelText, inputType, id, describedBy) => {
    const label = doc.createElement('label');
    label.setAttribute('for', id);
    label.textContent = labelText;

    const input = doc.createElement('input');
    input.setAttribute('type', inputType);
    input.setAttribute('id', id);
    if (describedBy) {
      input.setAttribute('aria-describedby', describedBy);
      input.setAttribute('autocomplete', inputType === 'email' ? 'email' : 'name');
    }
    return [label, input];
  };

  // Name field: real <label> properly associated via for/id
  form.append(...makeField('Name', 'text', 'name'));

  // Email field: correct input type, hint tied via aria-describedby
  form.append(...makeField('Email', 'email', 'email', 'email-hint'));

  // Hint element with an id so it can be referenced
  const hint = doc.createElement('div');
  hint.id = 'email-hint';
  hint.className = 'hint';
  hint.textContent = container.querySelector('.hint').textContent;
  form.append(hint);

  // Real submit button instead of clickable div
  const button = doc.createElement('button');
  button.type = 'submit';
  button.textContent = 'Submit';
  form.append(button);

  // Decorative image gets empty alt
  const img = container.querySelector('img');
  img.alt = '';
  form.append(img.cloneNode());

  return form.outerHTML;
}
"})
