result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-form/test/fix.test.js", "content": "// @vitest-environment jsdom
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import axe from 'axe-core';
import { parse } from 'node-html-parser';
import { fixForm } from '../src/fix.js';

const before = readFileSync(new URL('../fixtures/before.html', import.meta.url), 'utf8');

/** Injects html into the jsdom document body and runs axe-core on it. */
async function runAxe(html) {
  document.body.innerHTML = html;
  // color-contrast disabled: jsdom has no layout engine, so contrast
  // cannot be computed there (it would always report a false violation).
  const results = await axe.run(document.body, {
    rules: { 'color-contrast': { enabled: false } },
  });
  return results;
}

describe('before state', () => {
  it('has axe-core violations, including missing form labels', async () => {
    const results = await runAxe(before);
    expect(results.violations.length).toBeGreaterThan(0);
    const ruleIds = results.violations.map((v) => v.id);
    expect(ruleIds).toContain('label');
  });
});

describe('fixed form', () => {
  let results;

  it('passes axe-core with zero violations', async () => {
    results = await runAxe(fixForm(before));
    expect(
      results.violations.map((v) => `${v.id}: ${v.nodes.length} node(s)`),
    ).toEqual([]);
  });

  it('is wrapped in a real <form> element', () => {
    const root = parse(fixForm(before));
    expect(root.querySelector('form')).toBeTruthy();
  });

  it('associates every label with its input via for/id', () => {
    const root = parse(fixForm(before));
    for (const label of root.querySelectorAll('label')) {
      const htmlFor = label.getAttribute('for');
      expect(htmlFor, 'label must have a for attribute').toBeTruthy();
      const input = root.querySelector(`#${htmlFor}`);
      expect(input, `label[for="${htmlFor}"] must point to an element`).toBeTruthy();
      expect(input.tagName).toBe('INPUT');
    }
    expect(root.querySelectorAll('label').length).toBe(2);
  });

  it('uses the correct input types', () => {
    const root = parse(fixForm(before));
    expect(root.querySelector('#email')?.getAttribute('type')).toBe('email');
    expect(root.querySelector('#name')?.getAttribute('type')).toBe('text');
  });

  it('ties the hint to the email input via aria-describedby', () => {
    const root = parse(fixForm(before));
    const email = root.querySelector('#email');
    const hintId = email?.getAttribute('aria-describedby');
    expect(hintId).toBeTruthy();
    const hint = root.querySelector(`#${hintId}`);
    expect(hint?.text.trim()).toBe('We never share your email');
  });

  it('replaces the clickable div with a real submit button', () => {
    const root = parse(fixForm(before));
    const button = root.querySelector('button[type="submit"]');
    expect(button).toBeTruthy();
    expect(button.text.trim().toLowerCase()).toContain('submit');
    expect(root.querySelectorAll('[onclick]').length).toBe(0);
  });

  it('marks the decorative image as hidden from assistive tech', () => {
    const root = parse(fixForm(before));
    const img = root.querySelector('img[src="decor.png"]');
    expect(img?.getAttribute('alt')).toBe('');
  });
});
"})
